// Registry. Ids match what was saved before the redesign ("default" was the
// dino), so people keep their choice.
export const AVATARS: { id: string; name: string; bg: string; shapes: Shape[] }[] = [
  { id: "default", name: "dinosaur", bg: "#FFD6E9", shapes: DINOSAUR },
  { id: "avatar2", name: "rabbit", bg: "#FFE3D0", shapes: RABBIT },
  { id: "avatar3", name: "penguin", bg: "#FFE3EF", shapes: PENGUIN },
  { id: "avatar4", name: "squirrel", bg: "#FFCFE2", shapes: SQUIRREL },
  { id: "avatar5", name: "whale", bg: "#FFE9DC", shapes: WHALE },
  { id: "avatar6", name: "crocodile", bg: "#F9D9E8", shapes: CROCODILE },
];

export function getAvatar(id?: string | null) {
  return AVATARS.find((a) => a.id === id) ?? AVATARS[0];
}

// A round tile with the animal centred on a soft pastel background
export function Avatar({ id, size = 52 }: { id?: string | null; size?: number }) {
  const a = getAvatar(id);
  return (
    <View
      style={{
        width: size,
        height: size,
        borderRadius: size / 2,
        backgroundColor: a.bg,
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      <Svg width={size * 0.92} height={size * 0.92} viewBox="140 120 720 720">
        {a.shapes.map(([d, fill], i) => (
          <Path key={i} d={d} fill={fill} />
        ))}
      </Svg>
    </View>
  );
}
